<?php $isNew=$seasonId===null;$savePath=$isNew?'/write/journeys/new':'/write/journeys/'.$seasonId;$episodeValues=$episodeValues??null;?>
<main class="write-main journey-writer">
  <div class="writer-head"><div><a class="journey-back" href="<?=e(url('/write/journeys'))?>">← Startup Journeys</a><span class="writer-kicker"><?=$isNew?'Create a journey':'Journey settings and chapters'?></span><h1><?=$isNew?'A new journey':e(journeys_field($season,'title'))?></h1></div><div class="writer-actions"><?php if(!$isNew && journeys_field($season,'publication_status')==='published'):?><a class="wbtn" href="<?=e(url('/startup-journeys/'.journeys_field($season,'slug')))?>">View public journey ↗</a><?php endif;?><a class="wbtn" href="<?=e(url('/write'))?>">Writing library</a></div></div>
  <?php require __DIR__.'/../journeys/notices.php';?>
  <form method="post" action="<?=e(url($savePath))?>" class="journey-panel journey-form">
    <?=csrf_field()?><input type="hidden" name="action" value="save"><?php if(!$isNew):?><input type="hidden" name="row_version" value="<?=e(journeys_field($season,'row_version'))?>"><?php endif;?>
    <h2>The journey</h2><p class="journey-help">A journey contains the context. Chapters link to existing posts, which retain their own publication controls. Only one public journey can be planning, building or operating at a time; pause or conclude it before beginning another.</p>
    <div class="journey-fields-two"><div class="field"><label for="journey-title">Journey title</label><input id="journey-title" name="title" maxlength="180" required value="<?=e(journeys_field($season,'title'))?>"></div><div class="field"><label for="journey-venture">Venture name</label><input id="journey-venture" name="venture_name" maxlength="180" required value="<?=e(journeys_field($season,'venture_name'))?>"></div></div>
    <div class="field"><label for="journey-slug">Web address</label><input id="journey-slug" name="slug" maxlength="160" pattern="[a-z0-9]+(-[a-z0-9]+)*" value="<?=e(journeys_field($season,'slug'))?>" <?=!empty($season['published_at'])?'readonly':''?>><small class="journey-help">/startup-journeys/your-address. Use lowercase letters, numbers and hyphens. Leave blank to derive from the title. The address stays fixed after first publication.</small></div>
    <div class="journey-fields-three"><div class="field"><label for="journey-start">Venture start date <span class="optional">(optional)</span></label><input id="journey-start" name="started_on" type="date" value="<?=e(journeys_field($season,'started_on'))?>"></div><div class="field"><label for="journey-phase">Current phase</label><select id="journey-phase" name="phase"><?php foreach(journeys_phases() as $key=>$label):?><option value="<?=e($key)?>" <?=journeys_field($season,'phase','planning')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="field"><label for="journey-publication">Publication status</label><select id="journey-publication" name="publication_status"><?php foreach(journeys_publication_states() as $key=>$label):?><option value="<?=e($key)?>" <?=journeys_field($season,'publication_status','draft')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div></div>
    <div class="field"><label for="journey-summary">Public summary</label><textarea id="journey-summary" name="summary" rows="3" maxlength="1200"><?=e(journeys_field($season,'summary'))?></textarea><small class="journey-help">Required to publish. Up to 1,200 characters.</small></div>
    <div class="field"><label for="journey-baseline">Starting point / baseline</label><textarea id="journey-baseline" name="baseline" rows="6" maxlength="5000"><?=e(journeys_field($season,'baseline'))?></textarea><small class="journey-help">Required to publish. Describe the situation, starting resources, constraints and any initial metrics with their dates and basis.</small></div>
    <div class="field"><label for="journey-question">Learning question <span class="optional">(optional)</span></label><textarea id="journey-question" name="learning_question" rows="3" maxlength="1500"><?=e(journeys_field($season,'learning_question'))?></textarea></div>
    <div class="field"><label for="journey-outcomes">Public outcomes and lessons <span class="optional">(optional)</span></label><textarea id="journey-outcomes" name="outcomes" rows="5" maxlength="5000"><?=e(journeys_field($season,'outcomes'))?></textarea><small class="journey-help">Update as the journey develops. Separate results from assumptions and personal interpretation.</small></div>
    <details class="journey-private"><summary>Private working notes</summary><div class="field"><label for="journey-private-notes">Private notes</label><textarea id="journey-private-notes" name="private_notes" rows="5" maxlength="20000"><?=e(journeys_field($season,'private_notes'))?></textarea><small class="journey-help">These notes remain in the Writer record.</small></div></details>
    <div class="journey-form-actions"><button class="wbtn primary" type="submit"><?=$isNew?'Create journey':'Save journey'?></button><span class="journey-help">Choosing Published makes the journey’s public fields visible immediately.</span></div>
  </form>

  <?php if(!$isNew):?>
    <section class="journey-panel journey-writer-chapters" id="chapter-links"><div class="journey-section-head"><div><h2>Chapter links</h2><p class="journey-help">Set chapter numbers in the order the story unfolded. A chapter appears publicly only when its link is enabled and both the journey and its post are public.</p></div><a class="wbtn" href="<?=e(url('/write/new'))?>">Write a post</a></div>
      <datalist id="journey-post-options"><?php foreach($postOptions as $option):?><option value="<?=(int)$option['id']?>"><?=e($option['title'])?> (<?=e($option['status'])?>)</option><?php endforeach;?></datalist>
      <?php if(!$episodes):?><p class="journey-help">No chapters are linked yet. Add an existing post below.</p><?php endif;?>
      <?php foreach($episodes as $existingEpisode):$episodeForm=$existingEpisode;$formKey='chapter-'.(int)$existingEpisode['id'];$showError=$episodeValues&&journeys_field($episodeValues,'episode_id')===(string)$existingEpisode['id'];if($showError){$episodeForm=array_merge($episodeForm,$episodeValues);$episodeForm['is_published']=journeys_checked($episodeValues['is_published']??null)?1:0;}?>
        <details class="journey-episode-editor" <?=$showError?'open':''?>><summary><span>Chapter <?=(int)$existingEpisode['episode_order']?> · <?=e($existingEpisode['post_title'])?></span><small><?=$existingEpisode['is_published']?'Link enabled':'Private link'?> · <?=e($existingEpisode['post_status'])?></small></summary>
          <?php require __DIR__.'/journeys_episode_form.php';?>
          <form method="post" action="<?=e(url($savePath))?>" class="journey-remove-form"><?=csrf_field()?><input type="hidden" name="action" value="remove_episode"><input type="hidden" name="episode_id" value="<?=(int)$existingEpisode['id']?>"><button class="journey-text-button" type="submit">Remove this chapter link</button><span class="journey-help">The post stays in your writing library.</span></form>
        </details>
      <?php endforeach;?>
      <details class="journey-episode-editor" <?=(!$episodes||($episodeValues&&!journeys_field($episodeValues,'episode_id')))?'open':''?>><summary><span>Add a chapter</span><small>Link an existing post by ID</small></summary>
        <?php $episodeForm=($episodeValues&&!journeys_field($episodeValues,'episode_id'))?$episodeValues:['episode_order'=>($episodes?(int)max(array_column($episodes,'episode_order'))+1:1),'evidence_basis'=>'author_experience'];$formKey='chapter-new';require __DIR__.'/journeys_episode_form.php';?>
      </details>
    </section>
    <details class="journey-panel journey-delete"><summary>Remove this journey</summary><p>This removes the journey and its chapter links. The associated posts remain in the writing library.</p><form method="post" action="<?=e(url($savePath))?>"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="row_version" value="<?=e(journeys_field($season,'row_version'))?>"><label class="journey-check"><input type="checkbox" name="confirm_delete" value="1" required><span>I want to remove this journey and its chapter links.</span></label><button class="wbtn" type="submit">Remove journey</button></form></details>
  <?php endif;?>
</main>
